import React, { useEffect, useState } from "react";
import { Avatar, Button, Card, Dropdown, Form, Menu, Message, Modal, Select, Space, Tag, Typography} from "@arco-design/web-react";
import { AsyncButton, Selector } from "@/components/custom";
import Store from './store';
import { useObserver } from "mobx-react-lite";
import app from "@/store/app";
import { IconMore, IconMoreVertical } from "@arco-design/web-react/icon";
import { SchemaForm } from "@/components/schema";
import ajax from "@/utils/ajax";
import dev from "@/store/dev";
import project from "@/store/project";


const Version = () => {

    const [store] = useState(() => new Store());


    return useObserver(() => {
        const [form] = Form.useForm();
        const { visible, setVisible }  = store;

        useEffect(() => {
            store.setSelected(project.info.releaseVersion)
        },[])

        return (
            <div style={{ width: 1000, margin: '0 auto' }}>
                <Card 
                    title="版本管理"
                    extra={(
                        <Space>
                            <Button type="text"
                                onClick={() => {
                                    window.open(`#/project-view/${project.info.id}/admin/`)
                                }}
                            >
                                立即预览
                            </Button>
                            <Button type="primary"
                                onClick={() => {
                                    Modal.confirm({
                                        title: "保存提示",
                                        content: "请确认保存当前插件修改信息",
                                        onOk: () => {
                                            return ajax.post('/apijson/put', {
                                                Project: {
                                                    id: project.info.id,
                                                    releaseVersion: store.selected,
                                                }
                                            }).then(() => {
                                                Message.success("保存成功");
                                                project.getProjectInfo(project.info.id);
                                            })
                                        }
                                    })
                                }}
                            >
                                保存
                            </Button>
                        </Space>
                    )}
                >
                    <div style={{ display: "flex" }}>
                        <Form.Item label="默认版本" style={{ width: "80%" }}>
                            <Select
                                placeholder="请选择发布版本"
                                value={store.selected}
                                onChange={store.setSelected}
                                options={store.versions}
                            />
                        </Form.Item>
                        <Button type="primary" style={{ marginLeft: 10 }}
                            onClick={() => {
                                if(store.selected){
                                    window.open(`#/project-v/${project.info.id}/${store.selected}/admin/`)
                                }
                            }}
                        >预览</Button>
                    </div>
                </Card>
                <Card
                    style={{marginTop: 20}}
                    title="版本列表"
                    extra={(
                        <AsyncButton type="primary"
                            onClick={() => {
                                setVisible(true);
                                store.initValues = {
                                    versionNumber: store.incrementVersion()
                                }
                            }}
                        >
                            创建版本
                        </AsyncButton>
                    )}
                >
                        {store.list.map((item) => {
                            return (
                                <Card
                                    bordered
                                    key={item.id}
                                    style={{ marginBottom: 20 }}
                                    title={item.versionNumber}
                                    extra={(
                                        <Space>
                                            {item.isReleased? <Tag color="arcoblue">已发布</Tag> : <Tag>未发布</Tag>}
                                            <Button type="text"
                                                onClick={() => {
                                                    store.downItem = item;
                                                    window.open(`#/project-v/${project.info.id}/${item.versionNumber}/admin/`)
                                                }}
                                            >预览</Button>
                                            <Dropdown
                                                droplist={(
                                                    <Menu>
                                                        <Menu.Item key='1' disabled={item.isReleased}
                                                            onClick={() => {
                                                                ajax.post('/apijson/put', {
                                                                    ProjectVersion: {
                                                                        id: item.id,
                                                                        isReleased: 1,
                                                                    },
                                                                }).then(() => {
                                                                    Message.success("发布成功");
                                                                    store.init()
                                                                })
                                                            }}
                                                        >发布</Menu.Item>
                                                        <Menu.Item key='2' disabled={!item.isReleased}
                                                            onClick={() => {
                                                                Modal.confirm({
                                                                    title: "下架提示",
                                                                    content: "请确认是否下架当前版本",
                                                                    onOk: () => {
                                                                        return ajax.post('/apijson/put', {
                                                                            ProjectVersion: {
                                                                                id: item.id,
                                                                                isReleased: 0
                                                                            }
                                                                        }).then(() => {
                                                                            Message.success("下架成功")
                                                                            store.init()
                                                                        })
                                                                    }
                                                                })
                                                            }}
                                                        >下架</Menu.Item>
                                                    </Menu>
                                                )}
                                            >
                                                <Button icon={<IconMoreVertical />} />
                                            </Dropdown>
                                        </Space>
                                    )}
                                    actions={[
                                        <Typography.Text>
                                            发布时间：{item.createdAt}
                                        </Typography.Text>
                                    ]}
                                >
                                    <Card.Meta
                                        avatar={
                                        <Space>
                                            <Avatar size={24}>A</Avatar>
                                            <Typography.Text>{item.userId}</Typography.Text>
                                        </Space>
                                        }
                                        // title='Card Title'
                                        description={item.description}
                                    />
                                </Card>
                            )
                        })}
                </Card>
                <Modal
                    title="创建版本"
                    visible={visible}
                    onCancel={() => {
                        setVisible(false)
                    }}
                    onOk={() => {
                        return form.validate().then(async (res) => {
                            return store.createVersion(res);
                        })
                    }}
                    style={{ width: 800 }}
                    unmountOnExit
                >
                    <SchemaForm
                        form={form}
                        initialValues={store.initValues}
                        layout="vertical"
                        labelWidth={200}
                        generagteProps={{
                            cols: 24
                        }}
                        schema={store.schema}
                    />
                </Modal>
            </div>
        )
    })
}

export default Version;